import math

def dot_product(v1, v2):
    # multiplies matching positions and sums
    return sum(a * b for a, b in zip(v1, v2))

def magnitude(v):
    return math.sqrt(sum(a * a for a in v))

def cosine_similarity(v1, v2):
    return dot_product(v1, v2) / (magnitude(v1) * magnitude(v2))

query_embedding = [1, 2, 3]
short_chunk = [0.5, 1, 1.5]
long_chunk = [5, 10, 15]  # same direction, much larger magnitude

print("Comparing the same query against a short and a long chunk:\n")
for name, chunk in [("short_chunk", short_chunk), ("long_chunk", long_chunk)]:
    dp = dot_product(query_embedding, chunk)
    cos = cosine_similarity(query_embedding, chunk)
    print(f"  {name}: dot product={dp:.2f}, cosine similarity={cos:.3f}")

print("\nNotice dot product grows with magnitude, while cosine similarity stays constant.")
